-- Disposable database ONLY; all publication/revocation experiments roll back.
begin;
create temp table stable_snapshot_baseline as select id,to_jsonb(v) as snapshot from public.digital_proposal_versions v;
grant select on stable_snapshot_baseline to service_role;
set local role service_role;
do $$
declare
 agency uuid := '20000000-0000-4000-8000-000000000001'; report uuid := '40000000-0000-4000-8000-000000000001';
 version_a uuid := '72000000-0000-4000-8000-000000000001'; version_b uuid := '72000000-0000-4000-8000-000000000002';
 link_a uuid := '73000000-0000-4000-8000-000000000001'; link_b uuid := '73000000-0000-4000-8000-000000000002';
 session uuid := '75000000-0000-4000-8000-000000000001';
 report_stamp timestamptz; listing_stamp timestamptz; appraisal_stamp timestamptz; receipt jsonb; prior_receipt jsonb; after_revoke jsonb; rejected boolean; revision integer;
begin
 select r.updated_at,l.updated_at,a.updated_at into report_stamp,listing_stamp,appraisal_stamp
   from public.reports r join public.listings l on l.id=r.listing_id join public.str_appraisals a on a.report_id=r.id where r.id=report;
 assert not exists(select 1 from public.digital_proposal_links where is_primary), 'Migration must not silently adopt existing links';
 assert (select count(*) from public.digital_proposal_link_versions)=2, 'Legacy history backfill';
 assert (select count(*) from public.digital_proposal_events)=1, 'Legacy activity preserved';
 assert not has_function_privilege('authenticated','public.publish_digital_proposal_v3(uuid,uuid,integer,jsonb,text,text,text,integer,timestamptz,timestamptz,timestamptz)','execute');
 assert not has_function_privilege('anon','public.record_proposal_event_v2(text,uuid,uuid,uuid,text,text)','execute');
 assert not has_schema_privilege('authenticated','proposal_private','usage');
 receipt := public.publish_digital_proposal_v3(agency,report,1,'{"version":1,"fixture":"B"}',repeat('d',64),repeat('c',64),repeat('d',64),1,report_stamp,listing_stamp,appraisal_stamp);
 assert receipt->>'id'=version_b::text and receipt->>'link_id'=link_a::text and receipt->>'share_token'=repeat('b',64), 'First publication adopts newest existing token';
 assert (select version_id from public.digital_proposal_links where id=link_b)=version_b, 'Other legacy token remains fixed';
 assert (select count(*) from public.digital_proposal_link_versions where link_id=link_a)=2, 'Primary retains both served versions';
 perform public.record_proposal_event_v2(repeat('b',64),version_a,gen_random_uuid(),session,'open','proposal');
 perform public.record_proposal_event_v2(repeat('b',64),version_b,gen_random_uuid(),session,'open','proposal');
 assert (select count(*) from public.digital_proposal_events where link_id=link_a)=2, 'Dedup is per version, preserving old visible pages';
 perform public.record_proposal_event_v2(repeat('c',64),version_a,gen_random_uuid(),session,'open','proposal');
 assert not exists(select 1 from public.digital_proposal_events where link_id=link_b), 'Unserved version rejected';
 prior_receipt := (select to_jsonb(k) from public.digital_proposal_links k where id=link_a);
 revision := (public.save_digital_proposal(agency,report,1,'{"version":1,"fixture":"new draft"}')).revision;
 assert revision=2 and (select to_jsonb(k) from public.digital_proposal_links k where id=link_a)=prior_receipt, 'Autosave never advances publication';
 receipt := public.publish_digital_proposal_v3(agency,report,2,'{"version":1,"fixture":"A"}',repeat('e',64),repeat('b',64),repeat('e',64),1,report_stamp,listing_stamp,appraisal_stamp);
 assert receipt->>'id'=version_a::text and receipt->>'link_id'=link_a::text, 'A -> B -> A reuses snapshot and stable token';
 assert receipt->'share_link'->>'draft_revision'='2' and receipt->'share_link'->>'source_fingerprint'=repeat('e',64), 'Latest receipt differs from snapshot origin';
 assert not exists(select 1 from stable_snapshot_baseline b join public.digital_proposal_versions v on v.id=b.id where to_jsonb(v)<>b.snapshot), 'Snapshots and PDF paths remain byte-for-byte unchanged';
 assert public.list_appraisals(agency)->'rows' @> jsonb_build_array(jsonb_build_object('report_id',report,'proposal_status','Published')), 'Dashboard follows receipt for reused old snapshot';
 prior_receipt := (select to_jsonb(k) from public.digital_proposal_links k where id=link_a);
 rejected := false;
 begin perform public.publish_digital_proposal_v3(agency,report,1,'{}',repeat('f',64),repeat('f',64),repeat('f',64),1,report_stamp,listing_stamp,appraisal_stamp);
 exception when sqlstate 'PT409' then rejected := true; end;
 assert rejected and (select to_jsonb(k) from public.digital_proposal_links k where id=link_a)=prior_receipt, 'Stale publication does not advance pointer';
 rejected := false;
 begin perform public.publish_digital_proposal_v3(agency,report,2,'{"version":1,"fixture":"C"}',repeat('b',64),repeat('f',64),repeat('f',64),1,report_stamp,listing_stamp,appraisal_stamp);
 exception when unique_violation then rejected := true; end;
 assert rejected and (select to_jsonb(k) from public.digital_proposal_links k where id=link_a)=prior_receipt, 'Failed transaction retains prior publication';
 receipt := public.publish_digital_proposal_v3(agency,report,2,'{"version":1,"fixture":"A"}',repeat('f',64),repeat('b',64),repeat('e',64),1,report_stamp,listing_stamp,appraisal_stamp);
 assert receipt->>'id'=version_a::text and receipt->>'link_id'=link_a::text, 'Repeated publish is idempotent';
 update public.digital_proposal_links set revoked_at=now() where id=link_a;
 after_revoke := (select to_jsonb(k) from public.digital_proposal_links k where id=link_a);
 receipt := public.publish_digital_proposal_v3(agency,report,2,'{"version":1,"fixture":"A"}',repeat('f',64),repeat('b',64),repeat('e',64),1,report_stamp,listing_stamp,appraisal_stamp);
 assert receipt->>'link_id'<>link_a::text and receipt->>'link_id'<>link_b::text and receipt->>'share_token'=repeat('f',64), 'Revoked primary requires fresh URL, never another legacy URL';
 assert (select to_jsonb(k) from public.digital_proposal_links k where id=link_a)=after_revoke, 'Revoked primary never changes';
 rejected := false;
 begin update public.digital_proposal_links set revoked_at=null where id=link_a; exception when sqlstate 'PT409' then rejected:=true; end;
 assert rejected, 'Revoked token cannot be resurrected even by direct update';
 perform public.record_proposal_event_v2(repeat('b',64),version_a,gen_random_uuid(),gen_random_uuid(),'page','revoked');
 assert not exists(select 1 from public.digital_proposal_events where target='revoked'), 'Revoked token refuses tracking';
end $$;
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
do $$ begin assert (select count(*) from public.digital_proposal_link_versions)=0, 'Other agency cannot read history'; end $$;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
do $$ begin assert (select count(*) from public.digital_proposal_link_versions)>0, 'Own agency can read history'; end $$;
update public.reports set status='archived' where id='40000000-0000-4000-8000-000000000001';
do $$ begin assert not exists(select 1 from public.digital_proposal_links where report_id='40000000-0000-4000-8000-000000000001' and revoked_at is null), 'Authenticated archive revokes primary and legacy tokens'; end $$;
update public.reports set status='draft' where id='40000000-0000-4000-8000-000000000001';
do $$ begin assert not exists(select 1 from public.digital_proposal_links where report_id='40000000-0000-4000-8000-000000000001' and revoked_at is null), 'Restore does not restore old tokens'; end $$;
reset role;
rollback;
